-- Data only: posts the "Task Management now notifies on LINE" announcement once, to every company
-- that uses Task. `prisma migrate deploy` runs each migration a single time, so a later deploy never posts it again.
-- Four step-by-step pictures follow as attachments (shown inline under the post, in this order).
-- notifyEmail = 1 → lib/news-mail.ts emails it to all members within a minute of the deploy.
INSERT INTO `news` (`id`, `orgId`, `title`, `body`, `channel`, `audience`, `requiresAck`, `authorName`, `publishedAt`, `notifyEmail`)
SELECT
  CONCAT('tasklinenews', `o`.`id`),
  `o`.`id`,
  'Task Management แจ้งเตือนผ่าน LINE ได้แล้ว',
  'ตั้งแต่วันนี้ แจ้งเตือนจาก Task Management ส่งเข้า LINE ของคุณได้แล้ว ทั้งงานที่ได้รับมอบหมาย การถูกกล่าวถึง (mention) งานรออนุมัติ และงานใกล้ครบกำหนด อีเมลแจ้งเตือนยังส่งเหมือนเดิม ตั้งค่าครั้งเดียวประมาณ 2 นาที ตามขั้นตอนด้านล่าง (มีภาพประกอบทุกขั้นตอนท้ายประกาศ)

ขั้นที่ 1 · เชื่อม LINE ใน Portal
1. เข้า Portal แล้วกดไอคอนกระดิ่ง "ช่องทางรับแจ้งเตือน" มุมขวาบน (ข้างกระดิ่งประกาศ)
2. ที่หัวข้อ LINE / Telegram กดปุ่ม "เชื่อม LINE"
3. ระบบแสดง QR Code และรหัส ใช้ได้ภายในเวลาที่นับถอยหลัง
   - บนคอมพิวเตอร์: สแกน QR ด้วยแอป LINE บนมือถือ
   - บนมือถือ: กดลิงก์ "เปิดลิงก์ LINE"
4. ใน LINE กรอกอีเมลที่ใช้เข้า Portal แล้วยืนยัน
5. กลับมาที่ Portal กด "เชื่อมเสร็จแล้ว รีเฟรช" สถานะ LINE จะเปลี่ยนเป็น "เชื่อมแล้ว"
6. กด "ส่งข้อความทดสอบถึงฉัน" ถ้าได้รับข้อความใน LINE แปลว่าเชื่อมสำเร็จ

ขั้นที่ 2 · เปิดการส่งแจ้งเตือนใน Task Management
1. เข้า Task Management กดรูปโปรไฟล์มุมขวาบน แล้วเลือก My Account
2. ไปที่แท็บ Notifications
3. ติ๊ก "Also send my notifications to LINE / Telegram / Discord"
4. ช่องทางที่เชื่อมไว้จะแสดงอยู่ใต้ช่องนี้ ถ้ายังไม่ขึ้น กด Refresh

เรื่องที่ควรรู้
- ถ้ารหัสหมดเวลาก่อนเชื่อมเสร็จ กด "สร้างรหัสใหม่" แล้วทำขั้นที่ 1 ข้อ 3 อีกครั้ง
- ถ้าสถานะขึ้นว่า "บล็อกบัญชีแจ้งเตือนอยู่" ให้ปลดบล็อกบัญชีแจ้งเตือนในแอป LINE
- เชื่อม Telegram หรือ Discord เพิ่มได้จากหน้าเดียวกัน ถ้าเชื่อมไว้หลายช่องทาง เลือก "ใช้เป็นช่องทางหลัก" ได้ แจ้งเตือนจะส่งทางช่องทางหลัก และส่งอีกช่องทางเมื่อส่งไม่ถึง
- เลิกรับทาง LINE ได้ทุกเมื่อ ด้วยปุ่ม "ยกเลิก" ในหน้าช่องทางรับแจ้งเตือน
- ใช้อีเมลเดียวกันทั้งใน Portal และ Task ไม่อย่างนั้นแจ้งเตือนจะส่งไม่ถึง',
  'it',
  'all',
  0,
  'ฝ่าย IT',
  CURRENT_TIMESTAMP(3),
  1
FROM `orgs` `o`
WHERE `o`.`taskEnabled` = 1;

-- Picture 1 of 4 (56029 bytes)
INSERT INTO `news_attachments` (`id`, `newsId`, `name`, `mime`, `size`, `data`, `createdAt`)
SELECT CONCAT('tasklinefig1', `n`.`orgId`), `n`.`id`, '1 เปิดหน้าช่องทางรับแจ้งเตือน แล้วกดเชื่อม LINE.png', 'image/png', 56029, X'', CURRENT_TIMESTAMP(3) + INTERVAL 1 SECOND
FROM `news` `n`
WHERE `n`.`id` LIKE 'tasklinenews%';

